"use client";

import { useEffect, useRef } from "react";
import Image from "next/image";

/* HOSTPAY homepage v4. Single-file replacement for app/page.jsx.
   Embedded art: the approved HOSTPAY concept. No new package or CDN is needed.
   No wallet requests, signing, token deployment, purchases or financial data writes. */
const ART = {"brand": "data:image/webp;base64,", "mark": "data:image/webp;base64,", "robot": "data:image/webp;base64,", "earth": "data:image/webp;base64,", "nebula": "data:image/webp;base64,", "moons": ["data:image/webp;base64,", "data:image/webp;base64,", "data:image/webp;base64,", "data:image/webp;base64,", "data:image/webp;base64,", "data:image/webp;base64,", "data:image/webp;base64,", "data:image/webp;base64,", "data:image/webp;base64,", "data:image/webp;base64,"]};

/* Software 3D renderer: camera projection, ray/sphere surface normals, texture
   mapping, lighting and depth occlusion. No CSS-rotated discs or external library. */
function createHostpayScene(canvas, assets, onStatus) {
  const ctx=canvas.getContext('2d',{alpha:true});
  if(!ctx){onStatus('unavailable');return {setPaused(){},dispose(){}};}
  const TAU=Math.PI*2,eye=[0,.82,9.0],target=[0,.03,0];
  const dot=(a,b)=>a[0]*b[0]+a[1]*b[1]+a[2]*b[2];
  const sub=(a,b)=>a.map((v,i)=>v-b[i]);
  const norm=a=>{const d=Math.hypot(...a)||1;return a.map(v=>v/d);};
  const cross=(a,b)=>[a[1]*b[2]-a[2]*b[1],a[2]*b[0]-a[0]*b[2],a[0]*b[1]-a[1]*b[0]];
  const forward=norm(sub(target,eye)),right=norm(cross(forward,[0,1,0])),up=cross(right,forward);
  const light=norm([-.52,.63,.96]),half=norm([light[0],light[1],light[2]+1]);
  let w=1,h=1,dpr=1,focal=1,clock=0,raf=0,last=0,disposed=false,visible=true,ready=false,frames=0;
  const media=window.matchMedia('(prefers-reduced-motion: reduce)');let paused=media.matches;
  const textures=[],sprites=[],center=[0,.03,0];
  const colors=[[55,171,255],[161,108,255],[57,239,193],[219,91,255],[255,138,54],[255,176,53],[50,197,255],[184,105,255],[112,176,255],[104,201,255]];
  const names=['BONK','WIF','PEPE','POPCAT','DOGE','FLOKI','PENGU','MEW','PNUT','BRETT'];
  const orbits=[{r:2.55,inc:.30,roll:-.13},{r:2.85,inc:.62,roll:.12},{r:3.20,inc:.72,roll:-.14},{r:3.38,inc:.70,roll:.06}];
  const moons=Array.from({length:10},(_,i)=>({id:i,name:names[i],orbit:orbits[i%4],phase:.27+i*TAU/10,radius:.32+(i%3)*.026,period:19+i*1.37,color:colors[i]}));
  function point(o,a){const x=o.r*Math.cos(a),y=o.r*Math.sin(a)*Math.sin(o.inc),z=o.r*Math.sin(a)*Math.cos(o.inc),c=Math.cos(o.roll),s=Math.sin(o.roll);return [x*c-y*s,x*s+y*c,z];}
  function project(p){const d=sub(p,eye),z=dot(d,forward);return {x:w*.5+focal*dot(d,right)/z,y:h*.505-focal*dot(d,up)/z,z};}
  function texture(uri){return new Promise((resolve,reject)=>{const im=new window.Image();im.onload=()=>{const c=document.createElement('canvas');c.width=im.width;c.height=im.height;const cx=c.getContext('2d',{willReadFrequently:true});cx.drawImage(im,0,0);resolve({data:cx.getImageData(0,0,c.width,c.height).data,w:c.width,h:c.height});};im.onerror=reject;im.src=uri;});}
  function sample(t,u,v){const x=Math.min(t.w-1,Math.max(0,(u*t.w)|0)),y=Math.min(t.h-1,Math.max(0,(v*t.h)|0));return (y*t.w+x)*4;}
  function sphereSprite(index,diameter,spin,tilt){
    const size=Math.max(32,Math.min(index===0?240:100,Math.round(diameter*dpr)));
    let s=sprites[index];if(!s||s.size!==size){const c=document.createElement('canvas');c.width=c.height=size;s=sprites[index]={canvas:c,context:c.getContext('2d'),size,time:-999};}
    const interval=index===0?.085:.18;if(clock-s.time<interval&&s.time>=0)return s.canvas;s.time=clock;
    const image=s.context.createImageData(size,size),pixels=image.data,tex=textures[index===0?0:index+1],mark=textures[1],tint=index===0?[30,167,255]:colors[index-1];
    const cs=Math.cos(spin),sn=Math.sin(spin),ct=Math.cos(tilt),st=Math.sin(tilt),radius=size*.5;
    for(let y=0;y<size;y++)for(let x=0;x<size;x++){
      const nx=(x+.5-radius)/radius,ny=(radius-y-.5)/radius,q=nx*nx+ny*ny;if(q>=1)continue;
      const nz=Math.sqrt(1-q),px=(y*size+x)*4;
      // View-space normal -> world normal -> inverse axial tilt and spin.
      const wx=right[0]*nx+up[0]*ny-forward[0]*nz,wy=right[1]*nx+up[1]*ny-forward[1]*nz,wz=right[2]*nx+up[2]*ny-forward[2]*nz;
      const tx=ct*wx+st*wy,ty=-st*wx+ct*wy;
      const lx=cs*tx-sn*wz,ly=ty,lz=sn*tx+cs*wz;
      let r,g,b;
      if(index===0){
        let u=(Math.atan2(lz,lx)/TAU+1)%1,v=Math.acos(Math.max(-1,Math.min(1,ly)))/Math.PI;
        const j=sample(tex,u,v);r=tex.data[j];g=tex.data[j+1];b=tex.data[j+2];
        // An upright holographic emblem floats over the rotating geographical surface.
        const mu=nx/1.03+.5,mv=.5-(ny-.015)/1.05;
        if(mu>0&&mu<1&&mv>0&&mv<1&&nz>.55){const k=sample(mark,mu,mv),a=mark.data[k+3]/255;r=r*(1-a)+mark.data[k]*a;g=g*(1-a)+mark.data[k+1]*a;b=b*(1-a)+mark.data[k+2]*a;}
      }else{
        r=tint[0]*.10+2;g=tint[1]*.13+6;b=tint[2]*.17+15;
        const u=(lz<0?-lx:lx)/1.53+.5,v=.5-ly/1.53;
        if(u>0&&u<1&&v>0&&v<1&&Math.abs(lz)>.35){const j=sample(tex,u,v),a=tex.data[j+3]/255;r=r*(1-a)+tex.data[j]*a;g=g*(1-a)+tex.data[j+1]*a;b=b*(1-a)+tex.data[j+2]*a;}
      }
      const diffuse=Math.max(0,nx*light[0]+ny*light[1]+nz*light[2]),spec=Math.pow(Math.max(0,nx*half[0]+ny*half[1]+nz*half[2]),70),rim=Math.pow(1-nz,3.7),lum=.43+.79*diffuse;
      pixels[px]=Math.min(255,r*lum+spec*180+rim*tint[0]*1.5);
      pixels[px+1]=Math.min(255,g*lum+spec*226+rim*tint[1]*1.5);
      pixels[px+2]=Math.min(255,b*lum+spec*255+rim*tint[2]*1.5);
      pixels[px+3]=Math.min(255,(1-Math.sqrt(q))*radius*255);
    }
    s.context.putImageData(image,0,0);return s.canvas;
  }
  function occluded(p,bodies){const delta=sub(p,eye),distance=Math.hypot(...delta),dir=delta.map(v=>v/distance);for(const b of bodies){const oc=sub(eye,b.p),halfB=dot(oc,dir),disc=halfB*halfB-dot(oc,oc)+b.r*b.r;if(disc>=0){const t=-halfB-Math.sqrt(disc);if(t>.01&&t<distance-.025)return true;}}return false;}
  function glow(x,y,r,color,alpha){const grad=ctx.createRadialGradient(x,y,r*.38,x,y,r);grad.addColorStop(0,`rgba(${color},${alpha})`);grad.addColorStop(.58,`rgba(${color},${alpha*.34})`);grad.addColorStop(1,`rgba(${color},0)`);ctx.fillStyle=grad;ctx.beginPath();ctx.arc(x,y,r,0,TAU);ctx.fill();}
  function path3(points,bodies,color,alpha,lineWidth=1){ctx.beginPath();let active=false;for(const p of points){const s=project(p);if(s.z<=0||occluded(p,bodies)){active=false;continue;}if(active)ctx.lineTo(s.x,s.y);else{ctx.moveTo(s.x,s.y);active=true;}}ctx.strokeStyle=`rgba(${color},${alpha})`;ctx.lineWidth=lineWidth;ctx.stroke();}
  const paths=orbits.map(o=>Array.from({length:301},(_,i)=>point(o,i*TAU/300)));
  let seed=551;const rand=()=>{seed=(seed*1664525+1013904223)>>>0;return seed/4294967296;};
  const stars=Array.from({length:80},()=>({x:rand(),y:rand(),r:rand()*.8+.4,phase:rand()*TAU}));
  function render(){
    if(disposed||!ready)return;ctx.setTransform(dpr,0,0,dpr,0,0);ctx.clearRect(0,0,w,h);
    const bodies=[{id:0,p:center,r:2.00,color:[55,186,255]},...moons.map(m=>({id:m.id+1,p:point(m.orbit,m.phase+clock*TAU/m.period),r:m.radius,color:m.color}))];
    for(const s of stars){ctx.globalAlpha=.35+.35*Math.sin(clock*.8+s.phase);ctx.fillStyle='#73cbff';ctx.beginPath();ctx.arc(s.x*w,s.y*h,s.r,0,TAU);ctx.fill();}ctx.globalAlpha=1;
    const core=project(center);glow(core.x,core.y,focal*2.65/core.z,'19,105,255',.30);
    // A luminous base in world space, behind the planet.
    const baseCenter=project([0,-2.12,0]);glow(baseCenter.x,baseCenter.y,w*.27,'19,110,255',.12);
    for(let j=0;j<4;j++){const r=2.19-j*.22,y=-2.13+j*.04;const pts=Array.from({length:181},(_,i)=>{const a=i*TAU/180;return [Math.cos(a)*r,y,Math.sin(a)*r];});path3(pts,bodies,'41,166,255',.63-j*.06,1.6);}
    const sorted=bodies.map(b=>({...b,s:project(b.p)})).sort((a,b)=>b.s.z-a.s.z);
    for(const b of sorted){const r=focal*b.r/b.s.z;glow(b.s.x,b.s.y,r*1.45,b.color.join(','),b.id===0?.32:.42);const sprite=sphereSprite(b.id,r*2,b.id===0?clock*TAU/110+.25:clock*TAU/(55+b.id*2),b.id===0?-.12:.03);ctx.drawImage(sprite,b.s.x-r,b.s.y-r,r*2,r*2);ctx.strokeStyle=`rgba(${b.color.join(',')},.7)`;ctx.lineWidth=.8;ctx.beginPath();ctx.arc(b.s.x,b.s.y,r-.2,0,TAU);ctx.stroke();}
    ctx.save();ctx.globalCompositeOperation='screen';
    paths.forEach((p,i)=>{path3(p,bodies,i%2?'127,88,255':'43,186,255',.17,4);path3(p,bodies,i%2?'149,135,255':'96,222,255',.72,.9);});
    for(const m of moons){const a=m.phase+clock*TAU/m.period;for(let j=1;j<14;j++){const p=point(m.orbit,a-j*.024);if(occluded(p,bodies))continue;const s=project(p);glow(s.x,s.y,4.2-j*.19,m.color.join(','),.65*(1-j/14));}}
    ctx.restore();frames++;canvas.dataset.rendered='true';canvas.dataset.spheres='11';canvas.dataset.frames=String(frames);canvas.dataset.sceneTime=clock.toFixed(3);canvas.dataset.renderer='software-3d';
  }
  function resize(){const r=canvas.getBoundingClientRect();w=Math.max(1,r.width);h=Math.max(1,r.height);dpr=Math.min(window.devicePixelRatio||1,1.5);canvas.width=Math.round(w*dpr);canvas.height=Math.round(h*dpr);focal=h/(2*Math.tan(38*Math.PI/360));render();}
  function loop(now){raf=0;if(disposed||!ready)return;if(last)clock+=Math.min((now-last)/1000,.08);last=now;render();if(!paused&&visible&&!document.hidden)raf=requestAnimationFrame(loop);}
  function sync(){cancelAnimationFrame(raf);last=0;render();if(ready&&!disposed&&!paused&&visible&&!document.hidden)raf=requestAnimationFrame(loop);}
  const ro=new ResizeObserver(resize);ro.observe(canvas);const io=new IntersectionObserver(entries=>{visible=entries[0].isIntersecting;sync();},{threshold:.01});io.observe(canvas);
  const motionChanged=e=>{paused=e.matches;sync();};document.addEventListener('visibilitychange',sync);media.addEventListener('change',motionChanged);
  Promise.all([assets.earth,assets.mark,...assets.moons].map(texture)).then(ts=>{if(disposed)return;textures.push(...ts);ready=true;resize();onStatus('ready');sync();}).catch(()=>{if(!disposed)onStatus('unavailable');});
  return {setPaused(value){paused=value;sync();},dispose(){disposed=true;cancelAnimationFrame(raf);ro.disconnect();io.disconnect();document.removeEventListener('visibilitychange',sync);media.removeEventListener('change',motionChanged);sprites.length=0;textures.length=0;}};
}


const RULES = {
  overview: "HOSTPAY is being built as a Solana launchpad. The 1.2% platform fee is allocated 40% to developers, 30% to HOST-holder rewards, 20% to Treasury and 10% to the selected Host Community. Launching and automated mainnet rewards are not open in this preview.",
  fees: "The split of the 1.2% platform fee is 40 / 30 / 20 / 10. Developers receive SOL; the 30% holder and 10% community allocations buy HOST for rewards. Treasury supports operations and permitted delivery costs. These percentages are shares of the platform fee, not additional trading fees.",
  rewards: "The intended reward schedule begins approximately one hour after a child starts trading, then repeats every six hours. HOST purchases run independently of distribution times. Rewards depend on actual fees, eligibility and safe execution; they are not guaranteed income.",
  launch: "Planned developer access requires US$50 worth of HOST locked to launch, with no free opening-day exception. Final lock terms and price validation must be shown before signing. The launch app is not active here, so this page cannot lock funds or create tokens.",
  community: "Host Community eligibility starts at US$100 worth of the selected external Host token. The serviceable cohort expands each cycle as the child's delivery budget permits. The full 10% allocation buys HOST; cumulative community delivery costs are capped at 50% of that child's cumulative Treasury allocation.",
  provenance: "Verified wallet and transaction lookups are not connected to this preview. HOST is the native reward token. HPAY is the required child-mint address ending, not a reward token or an authenticity guarantee. The HOSTPAY on-chain registry is the authoritative authenticity check once connected.",
  ata: "HOSTPAY may fund creation of a recipient's HOST token account once per wallet across the ecosystem. If it is later closed, HOSTPAY will not pay to recreate it. There is no minimum HOST payout rule; delivery is bounded by the relevant child's Treasury budget."
};

function Icon({ name, size = 19, className = "" }) {
  const paths = {
    rocket: <><path d="M12 14c4-1 7-5 8-11-6 1-10 4-11 8l3 3Z"/><path d="m9 11-5-1-2 4 6 1 1 6 4-2-1-5M6 18l-3 3"/><circle cx="15" cy="8" r="1.5"/></>,
    code: <><path d="m8 6-6 6 6 6m8-12 6 6-6 6m-3-15-2 18"/></>,
    coins: <><ellipse cx="12" cy="5" rx="8" ry="3"/><path d="M4 5v5c0 4 16 4 16 0V5M4 10v5c0 4 16 4 16 0v-5M4 15v4c0 4 16 4 16 0v-4"/></>,
    treasury: <><path d="m2 8 10-6 10 6H2Zm3 3v8m5-8v8m4-8v8m5-8v8M2 22h20M3 19h18"/></>,
    community: <><circle cx="9" cy="7" r="3"/><circle cx="18" cy="8" r="2"/><path d="M3 21v-4a6 6 0 0 1 12 0v4H3Zm14-7a4 4 0 0 1 5 4v3h-5"/></>,
    shield: <><path d="m12 2 9 4v6c0 5-9 10-9 10S3 17 3 12V6l9-4Z"/><path d="m8 12 3 3 5-6"/></>,
    arrow: <><path d="M4 12h16m-6-6 6 6-6 6"/></>,
    send: <><path d="m3 3 19 9L3 21l3-9-3-9Zm3 9h16"/></>,
    clock: <><circle cx="12" cy="12" r="9"/><path d="M12 6v6l4 2"/></>,
    wallet: <><path d="M3 6h17v15H3V6Zm0 0V3h14v3M15 11h7v6h-7z"/><path d="M18 14h1"/></>,
    activity: <><path d="M3 21V11h4v10m3 0V3h4v18m3 0V8h4v13"/></>,
    external: <><path d="M14 3h7v7m0-7L10 14M10 4H3v17h17v-7"/></>
  };
  return <svg className={className} width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.65" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">{paths[name] || paths.shield}</svg>;
}

function Metric({ label, unit = "HOST", large = false }) {
  return <div className={large ? "hp-metric hp-metric-large" : "hp-metric"}><span>{label}</span><strong>— <small>{unit}</small></strong></div>;
}
function Distribution() {
  return <div className="hp-countdown"><Icon name="clock" size={17}/><span>Next distribution</span><strong>Not scheduled</strong></div>;
}
function Bucket({ type, share, title, subtitle, icon }) {
  const reward = type === "holders" || type === "communities";
  return <article className={`hp-bucket hp-${type}`}>
    <div className="hp-bucket-head"><div className="hp-bucket-icon"><Icon name={icon} size={26}/></div><div><strong className="hp-share">{share}%</strong><h3>{title}</h3></div><span className="hp-corner-light" aria-hidden="true"/></div>
    <p className="hp-bucket-caption">{subtitle}</p>
    {reward ? <>
      <div className="hp-reward-grid"><Metric label="Purchased with fees"/><Metric label="Distributed"/></div>
      <div className="hp-inventory"><span>Ready for a future distribution</span><strong>— HOST</strong><small>USD equivalent unavailable</small></div>
      <Distribution/>
    </> : <>
      <div className="hp-main-amount"><strong>— <small>SOL</small></strong><span>— USD equivalent</span></div>
      <div className="hp-detail-row"><span>{type === "developers" ? "Total paid to developers" : "Total Treasury allocation"}</span><b>— SOL</b></div>
      <div className="hp-detail-row"><span>{type === "developers" ? "Developers rewarded" : "Delivery costs funded"}</span><b>{type === "developers" ? "—" : "— SOL"}</b></div>
      <div className="hp-card-note">{type === "developers" ? "Authenticated creator attribution" : "Bounded operational funding"}</div>
    </>}
  </article>;
}

export default function HomePage() {
  const rootRef = useRef(null);
  const canvasRef = useRef(null);
  useEffect(() => {
    const root=rootRef.current,canvas=canvasRef.current;if(!root||!canvas)return;
    const status=root.querySelector('[data-scene-status]');
    let engine;
    try{engine=createHostpayScene(canvas,ART,state=>{root.dataset.scene=state;status.textContent=state==='ready'?'3D ecosystem visualization':'Animation unavailable in this browser';});}catch(e){root.dataset.scene='unavailable';status.textContent='Animation unavailable in this browser';console.error('HOSTPAY scene:',e.message);}
    const pause=root.querySelector('[data-motion]');const media=window.matchMedia('(prefers-reduced-motion: reduce)');let paused=media.matches;
    const updateMotion=()=>{pause.textContent=paused?'Resume motion':'Pause motion';pause.setAttribute('aria-pressed',String(paused));};updateMotion();
    const toggle=()=>{paused=!paused;updateMotion();engine?.setPaused(paused);};pause.addEventListener('click',toggle);
    const mediaChange=e=>{paused=e.matches;updateMotion();};media.addEventListener('change',mediaChange);
    const answer=root.querySelector('[data-robo-answer]'),input=root.querySelector('[data-robo-input]'),form=root.querySelector('[data-robo-form]');
    const showRule=key=>{answer.textContent=RULES[key];answer.hidden=false;};
    const onQuestion=e=>{const b=e.target.closest('[data-question]');if(b&&root.contains(b))showRule(b.dataset.question);};root.addEventListener('click',onQuestion);
    const ask=e=>{e.preventDefault();const q=input.value.trim().toLowerCase();if(!q)return;
      if(/(wallet|transaction|receive|received|authentic|verify|mint|hpay|registry)/.test(q))showRule('provenance');
      else if(/(ata|account creation|subsid)/.test(q))showRule('ata');
      else if(/(host commun|community|communities|100|treasury cap)/.test(q))showRule('community');
      else if(/(fee|split|40|30|20|10|econom)/.test(q))showRule('fees');
      else if(/(launch|developer|lock|50|build)/.test(q))showRule('launch');
      else if(/(reward|distribution|staking|income|payout)/.test(q))showRule('rewards');
      else if(/(hostpay|platform|host token|how.*work)/.test(q))showRule('overview');
      else{answer.textContent='This rules preview is limited to HOSTPAY. It does not have live on-chain lookups or a general AI model connected. Try asking about the fee split, developer access, rewards or Host Communities.';answer.hidden=false;}
    };form.addEventListener('submit',ask);
    const name=root.querySelector('[data-token-name]'),symbol=root.querySelector('[data-token-symbol]'),previewName=root.querySelector('[data-preview-name]'),previewSymbol=root.querySelector('[data-preview-symbol]');
    const preview=()=>{previewName.textContent=name.value.trim()||'Your project';previewSymbol.textContent=symbol.value.trim().toUpperCase()||'TICKER';};name.addEventListener('input',preview);symbol.addEventListener('input',preview);
    return()=>{engine?.dispose();pause.removeEventListener('click',toggle);media.removeEventListener('change',mediaChange);root.removeEventListener('click',onQuestion);form.removeEventListener('submit',ask);name.removeEventListener('input',preview);symbol.removeEventListener('input',preview);};
  }, []);

  return <main className="hp" ref={rootRef}>
    <style>{STYLES}</style>
    <a className="hp-skip" href="#economy">Skip to the economy</a>
    <div className="hp-wrap">
      <header className="hp-header" id="home">
        <a href="#home" className="hp-brand" aria-label="HOSTPAY home"><Image src={ART.brand} alt="HOSTPAY. Launch. Reward. Grow." width={222} height={52} unoptimized priority/></a>
        <nav aria-label="Main navigation" className="hp-nav"><a href="#home" className="hp-active">Home</a><a href="#how-it-works">How it works</a><a href="#economy">Economics</a><a href="#launchpad">Developers</a><a href="#communities">Communities</a><a href="#rewards">Rewards</a><a href="#ask-robo">ASK ROBO</a></nav>
        <div className="hp-header-actions"><span className="hp-chain"><i aria-hidden="true"/>Solana</span><button type="button" className="hp-wallet" disabled title="Wallet connection opens after the launch gates are complete"><Icon name="wallet" size={16}/>Connect Wallet<span className="hp-sr"> — not active yet</span></button></div>
      </header>

      <section className="hp-hero" aria-labelledby="hp-title" style={{ '--nebula': `url("${ART.nebula}")` }}>
        <div className="hp-hero-copy">
          <span className="hp-eyebrow">THE SOLANA LAUNCHPAD THAT GIVES BACK</span>
          <h1 id="hp-title">Launch.<br/>Reward.<br/><em>Grow.</em></h1>
          <p>A launchpad designed to share real platform fees with developers, HOST holders and selected host communities.</p>
          <div className="hp-hero-actions"><a className="hp-button hp-primary" href="#launchpad"><Icon name="rocket" size={17}/>Explore launching<Icon name="arrow" size={15}/></a><a className="hp-button hp-secondary" href="#how-it-works">How it works</a></div>
          <div className="hp-features"><div><Icon name="shield"/><span><strong>1.2% platform fee</strong><small>40 / 30 / 20 / 10</small></span></div><div><Icon name="coins"/><span><strong>Fee-funded rewards</strong><small>No staking required</small></span></div></div>
        </div>

        <div className="hp-world-area">
          <canvas ref={canvasRef} className="hp-world-canvas" role="img" aria-label="A slowly spinning three-dimensional HOSTPAY globe with ten illuminated spherical community planets orbiting through depth, in front of and behind the globe."/>
          <div className="hp-world-fallback"><Image src={ART.mark} width={110} height={115} alt="HOSTPAY" unoptimized/></div>
          <div className="hp-world-label">BUILD<br/>LAUNCH<br/>REWARD<br/>GROW<br/>TOGETHER</div>
          <div className="hp-world-controls"><span data-scene-status>Loading 3D ecosystem…</span><button type="button" data-motion aria-pressed="false">Pause motion</button></div>
          <span className="hp-art-note">Illustrative community artwork · not partnerships</span>
        </div>

        <aside id="ask-robo" className="hp-robo" aria-labelledby="robo-title">
          <div className="hp-robo-intro"><div className="hp-robo-name"><Image src={ART.mark} width={31} height={33} alt="" unoptimized/><div><h2 id="robo-title">ASK ROBO</h2><span className="hp-preview-dot">Rules preview</span></div></div><Image src={ART.robot} className="hp-robot" width={177} height={154} alt="ROBO, the HOSTPAY assistant" unoptimized/></div>
          <p className="hp-robo-tag">Your HOSTPAY intelligence centre.</p>
          <p className="hp-robo-copy">Explore the platform rules now. Verified launch, wallet and reward lookups are coming next.</p>
          <div className="hp-questions"><button data-question="overview" type="button">How does HOSTPAY work?<Icon name="arrow" size={13}/></button><button data-question="fees" type="button">Explain the 1.2% split<Icon name="arrow" size={13}/></button><button data-question="launch" type="button">How do I launch?<Icon name="arrow" size={13}/></button><button data-question="rewards" type="button">How do rewards work?<Icon name="arrow" size={13}/></button></div>
          <form data-robo-form className="hp-robo-form"><label htmlFor="hp-robo-question" className="hp-sr">Ask about HOSTPAY platform rules</label><input id="hp-robo-question" data-robo-input placeholder="Ask about HOSTPAY…" maxLength={300} autoComplete="off"/><button type="submit" aria-label="Ask ROBO"><Icon name="send" size={20}/></button></form>
          <div className="hp-robo-answer" data-robo-answer hidden role="status" aria-live="polite"/>
          <small className="hp-robo-disclosure"><Icon name="shield" size={12}/>HOSTPAY only · approved rules, not live AI or on-chain data</small>
        </aside>
      </section>

      <section id="economy" className="hp-economy hp-panel" aria-labelledby="economy-title">
        <div className="hp-section-head"><div><h2 id="economy-title"><Icon name="rocket" size={25}/>HOSTPAY ECONOMY <span>— PRE-LAUNCH</span></h2><p>One platform fee. Four destinations. Accumulation, purchases and payouts will be independently verifiable.</p></div><span className="hp-data-state">Live data not connected</span></div>
        <div className="hp-economy-grid">
          <div className="hp-fee-visual" aria-label="1.2% platform fee, divided 40, 30, 20, 10"><div className="hp-fee-ring"><i/><div><strong>1.2%</strong><span>Platform fee</span></div></div><svg className="hp-fee-streams" viewBox="0 0 85 170" aria-hidden="true"><path d="M0 85C45 85 24 8 85 8M0 85C45 85 35 59 85 59M0 85C45 85 35 111 85 111M0 85C45 85 24 162 85 162"/></svg></div>
          <div className="hp-buckets"><Bucket type="developers" share="40" title="Developers" subtitle="Paid in SOL to authenticated creators" icon="code"/><Bucket type="holders" share="30" title="HOST Holders" subtitle="Market-purchased HOST rewards" icon="coins"/><Bucket type="treasury" share="20" title="Treasury / Operations" subtitle="Infrastructure and bounded delivery" icon="treasury"/><Bucket type="communities" share="10" title="Host Communities" subtitle="HOST for qualifying community holders" icon="community"/></div>
        </div>
        <div id="rewards" className="hp-economy-foot"><span><Icon name="clock" size={13}/>Distribution target: first ~1 hour, then every 6 hours.</span><span>HOST purchases run separately. No public purchase countdown.</span></div>
      </section>

      <section className="hp-dashboard" aria-label="Launchpad and platform activity">
        <article id="launchpad" className="hp-launch hp-panel">
          <div className="hp-panel-heading"><h2><Icon name="rocket" size={22}/>LAUNCHPAD</h2><span className="hp-tag">Interface preview</span></div><p className="hp-subtitle">Prepare a launch into an existing community. Signing and deployment remain closed.</p>
          <ol className="hp-steps">{['Connect wallet','Configure token','Choose host','Review economics','Launch'].map((step,i)=><li key={step}><span>{i+1}</span><small>{step}</small></li>)}</ol>
          <div className="hp-launch-form"><div><label htmlFor="hp-token-name">Token name</label><input id="hp-token-name" data-token-name placeholder="Your project" maxLength={32}/></div><div><label htmlFor="hp-token-symbol">Token symbol</label><input id="hp-token-symbol" data-token-symbol placeholder="TICKER" maxLength={10}/></div><div className="hp-token-preview"><Image src={ART.mark} width={28} height={30} alt="" unoptimized/><span><b data-preview-symbol>TICKER</b><small data-preview-name>Your project</small></span></div></div>
          <div className="hp-launch-rules"><span>Required mint ending <b>…HPAY</b></span><span>Planned access <b>US$50 in HOST</b></span></div><p className="hp-mint-note">HPAY brands the mint address, not the ticker. Registry verification remains the authenticity proof. Lock terms are shown before signing.</p>
          <button className="hp-launch-disabled" type="button" disabled><Icon name="wallet" size={15}/>Public launching is not open yet</button>
        </article>

        <article className="hp-recent hp-panel"><div className="hp-panel-heading"><h2>RECENT LAUNCHES</h2><span className="hp-tag">Registry feed</span></div><div className="hp-tabs" aria-label="Launch data status"><span className="hp-selected">Launches</span><span>Host community</span><span>Activity</span></div><div className="hp-table-head"><span>TOKEN</span><span>HOST</span><span>STATUS</span></div><div className="hp-empty"><Icon name="shield" size={32}/><strong>Verified launches will appear here</strong><p>The production registry feed is not connected. No example launches are shown as real activity.</p><span className="hp-empty-line"/><span className="hp-empty-line short"/></div></article>

        <article className="hp-activity hp-panel"><div className="hp-panel-heading"><h2>PLATFORM ACTIVITY</h2><span className="hp-tag">Pending</span></div><div className="hp-stats"><div><Icon name="rocket"/><strong>—</strong><span>Launches</span></div><div><Icon name="activity"/><strong>— SOL</strong><span>Volume</span></div><div><Icon name="community"/><strong>—</strong><span>Wallets reached</span></div></div><div className="hp-empty-chart"><div className="hp-chart-grid" aria-hidden="true"/><div><Icon name="activity" size={25}/><strong>Waiting for real platform data</strong><span>No simulated earnings or volume.</span></div></div></article>
      </section>

      <section id="how-it-works" className="hp-explainer"><div><span className="hp-kicker">REAL FEES. SHARED PARTICIPATION.</span><h2>Launch. Reward. Grow.</h2><p>The goal is an ecosystem funded by genuine platform activity, not promised returns or inflationary reward emissions.</p></div><div className="hp-faq"><details><summary>What is the developer requirement?</summary><p>The planned launch requirement is US$50 worth of HOST locked at launch. This is an access rule, not a quality guarantee. The qualified price and final lock terms must be available before signing.</p></details><details id="communities"><summary>How do Host Communities receive rewards?</summary><p>Eligible wallets hold at least US$100 of the selected external Host token. The recipient cohort expands as that child’s delivery budget grows. The entire 10% community allocation buys HOST. Delivery costs come from Treasury and cannot cumulatively exceed 50% of that child’s Treasury allocation.</p></details><details><summary>Why did a wallet receive HOST?</summary><p>Verified provenance will identify the child launch, selected community, applicable reward cycle and payout transaction. This preview cannot verify wallets or transactions. A mint ending in HPAY is branding; registry data is the authenticity proof.</p></details></div></section>
      <footer className="hp-footer"><span>HOSTPAY <b>•</b> Built on Solana</span><p>Under active development. Mainnet launching, market purchases and automatic payouts remain subject to technical validation and security review. Rewards depend on actual activity and eligibility, and are not guaranteed.</p><a href="https://x.com/HOSTPAY_SOL" target="_blank" rel="noopener noreferrer">@HOSTPAY_SOL<Icon name="external" size={13}/></a></footer>
    </div>
  </main>;
}

